-- link imported quant-evidence problems to skill keywords
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_QUANT=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

do $kw$
declare v_map constant jsonb := $satx${"quant-pair-compare-20261027":"command_of_evidence_quant","quant-ratio-vs-baseline-20261090":"command_of_evidence_quant","quant-target-met-20261097":"command_of_evidence_quant","quant-max-change-20261104":"command_of_evidence_quant","quant-max-step-20261111":"command_of_evidence_quant","quant-pair-compare-20261118":"command_of_evidence_quant","quant-ratio-vs-baseline-20261293":"command_of_evidence_quant","quant-target-met-20261300":"command_of_evidence_quant","quant-max-change-20261307":"command_of_evidence_quant","quant-max-step-20261314":"command_of_evidence_quant","quant-pair-compare-20261321":"command_of_evidence_quant","quant-ratio-vs-baseline-20261356":"command_of_evidence_quant","quant-target-met-20261363":"command_of_evidence_quant","quant-max-change-20261370":"command_of_evidence_quant","quant-max-step-20261377":"command_of_evidence_quant","quant-pair-compare-20261384":"command_of_evidence_quant","quant-ratio-vs-baseline-20261447":"command_of_evidence_quant","quant-target-met-20261454":"command_of_evidence_quant","quant-max-change-20261461":"command_of_evidence_quant","quant-max-step-20261468":"command_of_evidence_quant","quant-pair-compare-20261475":"command_of_evidence_quant","quant-ratio-vs-baseline-20261622":"command_of_evidence_quant","quant-target-met-20261636":"command_of_evidence_quant","quant-max-change-20261678":"command_of_evidence_quant","quant-max-step-20261685":"command_of_evidence_quant","quant-pair-compare-20261692":"command_of_evidence_quant","quant-ratio-vs-baseline-20261727":"command_of_evidence_quant","quant-target-met-20261741":"command_of_evidence_quant","quant-max-change-20261755":"command_of_evidence_quant","quant-max-step-20261762":"command_of_evidence_quant","quant-pair-compare-20261769":"command_of_evidence_quant","quant-ratio-vs-baseline-20261874":"command_of_evidence_quant","quant-target-met-20261888":"command_of_evidence_quant","quant-max-change-20261923":"command_of_evidence_quant","quant-max-step-20261930":"command_of_evidence_quant","quant-pair-compare-20261937":"command_of_evidence_quant"}$satx$::jsonb; v_n int;
begin
  insert into problem_keywords (problem_id, keyword_id)
  select distinct p.id, k.id from jsonb_each_text(v_map) m
    join problem_versions pv on pv.quality->'mockExamGeneration'->>'gid' = m.key
    join problems p on p.id = pv.problem_id and p.archived_at is null
    join subject_keywords k on k.subject_id = p.subject_id and k.skill_code = m.value
  on conflict (problem_id, keyword_id) do nothing;
  get diagnostics v_n = row_count;
  raise notice 'keyword links inserted: % (of % mapped gids)', v_n, (select count(*) from jsonb_object_keys(v_map));
end
$kw$;
